#!/usr/bin/env node
// Builds the docs Changelog page from the repository's CHANGELOG.md.
//
// CHANGELOG.md is generated by scripts/version.mjs and links every entry to a
// commit and a compare page. Those pages are not public (or not in this
// repository), so the docs page keeps the version headings and the text and
// drops the commit and compare links.
//
//   node scripts/sync-changelog.mjs           write the page
//   node scripts/sync-changelog.mjs --check   fail if the page is out of date
//
// The same script runs in the private repository and in the public snapshot.
import { existsSync, readFileSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";
import { stripLinks, topVersion } from "../../scripts/changelog-parse.mjs";

export { topVersion };

const root = join(dirname(fileURLToPath(import.meta.url)), "..", "..");
const SOURCE = join(root, "CHANGELOG.md");
const PAGE = join(root, "docs-site", "src", "content", "docs", "reference", "changelog.mdx");
const PACKAGE = join(root, "package.json");

const FRONTMATTER = `---
title: Changelog
description: What changed in each release of Nuits Receipts, from CHANGELOG.md.
sidebar:
  order: 11
---

This page is built from \`CHANGELOG.md\` in the repository by \`docs-site/scripts/sync-changelog.mjs\`, with commit and compare links removed. \`scripts/version.mjs\` generates the entries from Conventional Commits on every release. The first release run planted the \`v0.1.0\` baseline from \`package.json\`; entries start after it.

To read the releases as a comic, one receipt slip per release, see the [changelog on the project site](https://receipts.nuits.net/changelog/).

`;

// Pure: CHANGELOG.md text in, docs page text out.
export function docsChangelog(markdown) {
  const start = markdown.search(/^## /m);
  if (start < 0) throw new Error("CHANGELOG.md has no release entries.");
  let body = markdown.slice(start).replace(/\r\n?/g, "\n");
  body = stripLinks(body);
  // MDX reads "{" and "<" outside code as markup.
  body = body
    .split("\n")
    .map((line) =>
      line
        .split(/(`[^`]*`)/)
        .map((part, i) => (i % 2 ? part : part.replace(/\{/g, "\\{").replace(/</g, "&lt;")))
        .join(""),
    )
    .join("\n");
  return `${FRONTMATTER}${body.trimEnd()}\n`;
}

if (process.argv[1] && fileURLToPath(import.meta.url) === process.argv[1]) {
  const source = readFileSync(SOURCE, "utf8");
  const page = docsChangelog(source);
  const pkg = JSON.parse(readFileSync(PACKAGE, "utf8"));
  if (process.argv.includes("--check")) {
    const problems = [];
    if (topVersion(source) !== pkg.version)
      problems.push(`CHANGELOG.md starts at ${topVersion(source)} but package.json is ${pkg.version}.`);
    if (!existsSync(PAGE) || readFileSync(PAGE, "utf8") !== page)
      problems.push("docs-site changelog page is out of date. Run: node docs-site/scripts/sync-changelog.mjs");
    if (problems.length) {
      for (const p of problems) console.error(p);
      process.exit(1);
    }
    console.log("Changelog page is up to date.");
  } else {
    writeFileSync(PAGE, page);
    console.log(`Wrote ${PAGE.slice(root.length + 1)} from CHANGELOG.md.`);
  }
}
